 虚拟化检查通过 
&quot; else echo -e &quot;
 不支持当前虚拟化，退出…… 
&quot; exit 1 fi&#125;# 取消交换分区unset_swap()&#123; if [[ -e /swap/swapfile ]] || [[ -e /swap ]] || [[ `free | grep -i swap | awk -F &quot; &quot; &#x27;&#123;print $2&#125;&#x27;` -ne 0 ]];then swapoff -a rm -rf /swap sed -i &#x27;/swap/d&#x27; /etc/fstab if [[ -e /swap/swapfile ]] || [[ -e /swap ]] || [[ `free | grep -i swap | awk -F &quot; &quot; &#x27;&#123;print $2&#125;&#x27;` -ne 0 ]];then echo -e &quot;
 删除失败，写保护 
&quot; else echo -e &quot;
 删除完成 
&quot; fi else echo -e &quot;
 删除失败，没有找到虚拟内存 
&quot; fi&#125;# 设置交换分区set_swap()&#123; echo -e &quot; 开始设置虚拟内存容量，建议为内存的2倍。但过大的交换分区会影响磁盘IO，请悉知。 &quot; read -p &quot; 请输入需要添加的虚拟内存容量，单位MB: &quot; swap_capacity if [[ -e /swap/swapfile ]] || [[ -e /swap ]] || [[ `free | grep -i swap | awk -F &quot; &quot; &#x27;&#123;print $2&#125;&#x27;` -ne 0 ]];then read -e -p &quot; 交换分区文件已存在，继续创建会删除以前的交换分区，是否继续创建？ [Y/n] :&quot; yn [[ -z &quot;$&#123;yn&#125;&quot; ]] &amp;&amp; yn=&quot;y&quot; if [[ $yn == [Yy] ]]; then unset_swap mkdir /swap dd if=/dev/zero of=/swap/swapfile bs=1MB count=$swap_capacity mkswap /swap/swapfile chmod 600 /swap/swapfile swapon /swap/swapfile sed -i &#x27;/swap/d&#x27; /etc/fstab echo &quot;/swap/swapfile swap swap defaults 0 0&quot; &gt;&gt;/etc/fstab if [[ -e /swap/swapfile ]] || [[ -e /swap ]] || [[ `free | grep -i swap | awk -F &quot; &quot; &#x27;&#123;print $2&#125;&#x27;` -ne 0 ]];then echo -e &quot;
 新的虚拟内存设置完成 
&quot; else echo -e &quot;
 设置失败，启动删除程序 
&quot; unset_swap fi else echo -e &quot;
 用户取消，程序退出 
&quot; exit 1 fi else echo &quot; &quot; # 为了美观输出一个空行 mkdir /swap dd if=/dev/zero of=/swap/swapfile bs=1MB count=$swap_capacity mkswap /swap/swapfile chmod 600 /swap/swapfile swapon /swap/swapfile sed -i &#x27;/swap/d&#x27; /etc/fstab echo &quot;/swap/swapfile swap swap defaults 0 0&quot; &gt;&gt;/etc/fstab if [[ -e /swap/swapfile ]] || [[ -e /swap ]] || [[ `free | grep -i swap | awk -F &quot; &quot; &#x27;&#123;print $2&#125;&#x27;` -ne 0 ]];then echo -e &quot;
 虚拟内存设置完成 
